package app.dawnbreaker.mobile;
import android.content.*;import android.database.Cursor;import android.database.sqlite.*;import org.json.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
final class PlaybackLedger {
 private final Context context;private static Helper helper;private static final AtomicBoolean sending=new AtomicBoolean();
 private static class Helper extends SQLiteOpenHelper{Helper(Context c){super(c,"playback-offline.db",null,1);}public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE segments(id TEXT PRIMARY KEY,account TEXT,track TEXT,start REAL,end REAL,seconds REAL)");d.execSQL("CREATE INDEX segments_account ON segments(account)");}public void onUpgrade(SQLiteDatabase d,int old,int current){}}
 PlaybackLedger(Context c){context=c.getApplicationContext();synchronized(PlaybackLedger.class){if(helper==null)helper=new Helper(context);}}
 private SQLiteDatabase db(){return helper.getWritableDatabase();}
 void add(String track,double seconds,double end){String uid=MediaStore.prefs(context).getString("account","");if(!uid.matches("[a-f0-9]{32}")||seconds<.1)return;ContentValues v=new ContentValues();v.put("id",UUID.randomUUID().toString());v.put("account",uid);v.put("track",track);v.put("start",end-Math.min(seconds,120));v.put("end",end);v.put("seconds",Math.min(seconds,120));db().insertOrThrow("segments",null,v);sync();}
 double pendingSeconds(){String uid=MediaStore.prefs(context).getString("account","");try(Cursor rows=db().rawQuery("SELECT COALESCE(SUM(seconds),0) FROM segments WHERE account=?",new String[]{uid})){return rows.moveToFirst()?rows.getDouble(0):0;}}
 void sync(){if(!OfflineProxy.connected(context)||!sending.compareAndSet(false,true))return;MediaStore.IO.execute(()->{try{String uid=MediaStore.prefs(context).getString("account","");String device=OfflineProxy.prefs(context).getString("device","");if(device.isEmpty()){device=UUID.randomUUID().toString();OfflineProxy.prefs(context).edit().putString("device",device).apply();}
  for(int attempt=0;attempt<20;attempt++){JSONArray segments=new JSONArray();try(Cursor rows=db().rawQuery("SELECT * FROM segments WHERE account=? ORDER BY start LIMIT 100",new String[]{uid})){while(rows.moveToNext())segments.put(new JSONObject().put("id",rows.getString(rows.getColumnIndexOrThrow("id"))).put("track_id",rows.getString(rows.getColumnIndexOrThrow("track"))).put("start",rows.getDouble(rows.getColumnIndexOrThrow("start"))).put("end",rows.getDouble(rows.getColumnIndexOrThrow("end"))).put("seconds",rows.getDouble(rows.getColumnIndexOrThrow("seconds"))));}
   if(segments.length()==0)break;if(!uid.equals(MediaStore.prefs(context).getString("account","")))break;
   JSONObject response=MediaStore.request(context,"/api/plugins/music/sync",new JSONObject().put("account_id",uid).put("device_id",device).put("segments",segments));if(response.optDouble("credited_seconds",0)>0)OfflineProxy.prefs(context).edit().putString("sync_revision",UUID.randomUUID().toString()).apply();JSONArray accepted=response.optJSONArray("accepted_ids");if(accepted!=null)for(int i=0;i<accepted.length();i++)db().delete("segments","id=? AND account=?",new String[]{accepted.getString(i),uid});JSONArray rejected=response.optJSONArray("rejected_ids");if(rejected!=null&&rejected.length()>0){OfflineProxy.prefs(context).edit().putString("sync_error","部分听曲记录的设备时间异常，尚未同步。请检查系统时间。").apply();break;}
  }
 }catch(Exception ignored){}finally{sending.set(false);}});}
}
